+                            <input type="email" @bind="_references[index].Email" placeholder="Reference email" />
+                        </div>
+                        <div class="form-group">
+                            <label>Phone *</label>
+                            <input type="tel" @bind="_references[index].Phone" placeholder="Reference phone" />
+                        </div>
+                    </div>
+                }
+                @if (_references.Count < 3)
+                {
+                    <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
+                }
+                <div class="step-buttons">
+                    <button class="btn-back" @onclick="PrevStep">Back</button>
+                    <button class="btn-next" @onclick="NextStep">Next</button>
+                </div>
+            </div>
+        }
+
+        <!-- Step 4: Cover Letter -->
+        @if (_currentStep == 3)
+        {
+            <div class="step-content">
+                <h2>Cover Letter</h2>
+                <div class="form-group">
+                    <label for="coverLetter">Write your cover letter</label>
+                    <textarea id="coverLetter" @bind="_coverLetter" @bind:event="oninput" rows="12" placeholder="Tell us why you're a great fit..." maxlength="2000"></textarea>
+                    <div class="char-count">@_coverLetter.Length / 2000 characters</div>
+                </div>
+                <div class="step-buttons">
+                    <button class="btn-back" @onclick="PrevStep">Back</button>
+                    <button class="btn-next" @onclick="NextStep">Next</button>
+                </div>
+            </div>
+        }
+
+        <!-- Step 5: Review & Submit -->
+        @if (_currentStep == 4)
+        {
+            <div class="step-content">
+                <h2>Review &amp; Submit</h2>
+
+                <div class="review-section">
+                    <div class="review-header">
+                        <h3>Personal Information</h3>
+                        <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
+                    </div>
+                    <dl>
+                        <dt>Full Name</dt><dd>@_fullName</dd>
+                        <dt>Email</dt><dd>@_email</dd>
+                        <dt>Phone</dt><dd>@_phone</dd>
+                        <dt>Address</dt><dd>@_address</dd>
+                    </dl>
+                </div>
+
+                <div class="review-section">
+                    <div class="review-header">
+                        <h3>Work History</h3>
+                        <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
+                    </div>
+                    @foreach (var entry in _workEntries)
+                    {
+                        <div class="review-entry">
+                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
+                            <span>@entry.StartDate.ToString("MMM yyyy") &mdash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
+                            @if (!string.IsNullOrWhiteSpace(entry.Description))
+                            {
+                                <p>@entry.Description</p>
+                            }
+                        </div>
+                    }
+                </div>
+
+                <div class="review-section">
+                    <div class="review-header">
+                        <h3>References</h3>
+                        <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
+                    </div>
+                    @foreach (var reference in _references)
+                    {
+                        <div class="review-entry">
+                            <strong>@reference.Name</strong> (@reference.Relationship)<br />
+                            <span>@reference.Email &bull; @reference.Phone</span>
+                        </div>
+                    }
+                </div>
+
+                <div class="review-section">
+                    <div class="review-header">
+                        <h3>Cover Letter</h3>
+                        <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
+                    </div>
+                    <p class="cover-letter-preview">@_coverLetter</p>
+                </div>
+
+                <div class="step-buttons">
+                    <button class="btn-back" @onclick="PrevStep">Back</button>
+                    <button class="btn-submit" @onclick="SubmitApplication" disabled="@_isSubmitting">
+                        @(_isSubmitting ? "Submitting..." : "Submit Application")
+                    </button>
+                </div>
+            </div>
+        }
+    }
+    else
+    {
+        <!-- Confirmation -->
+        <div class="confirmation">
+            <div class="confirmation-icon">&#10003;</div>
+            <h2>Application Submitted!</h2>
+            <p>Thank you for your application. Your application ID is:</p>
+            <div class="application-id">@_applicationId</div>
+            <p>We will review your application and get back to you soon.</p>
+        </div>
+    }
+</div>
+
+@code {
+    private readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+    private int _currentStep = 0;
+    private string _errorMessage = string.Empty;
+    private bool _isValidating = false;
+    private bool _isSubmitting = false;
+    private bool _submitted = false;
+    private int _applicationId;
+
+    // Step 1: Personal Info
+    private string _fullName = string.Empty;
+    private string _email = string.Empty;
+    private string _phone = string.Empty;
+    private string _address = string.Empty;
+
+    // Step 2: Work History
+    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
+
+    // Step 3: References
+    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4: Cover Letter
+    private string _coverLetter = string.Empty;
+
+    private string GetStepClass(int stepIndex)
+    {
+        if (stepIndex == _currentStep) return "active";
+        if (stepIndex < _currentStep) return "completed";
+        return "future";
+    }
+
+    private void NavigateToStep(int stepIndex)
+    {
+        if (stepIndex < _currentStep)
+        {
+            _currentStep = stepIndex;
+            _errorMessage = string.Empty;
+        }
+    }
+
+    private void GoToStep(int step)
+    {
+        _currentStep = step;
+        _errorMessage = string.Empty;
+    }
+
+    private async Task NextStep()
+    {
+        _errorMessage = string.Empty;
+
+        if (!ValidateCurrentStep())
+            return;
+
+        if (_currentStep == 0)
+        {
+            _isValidating = true;
+            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
+            _isValidating = false;
+
+            if (!emailValid)
+            {
+                _errorMessage = "Please enter a valid email address.";
+                return;
+            }
+        }
+
+        _currentStep++;
+    }
+
+    private void PrevStep()
+    {
+        if (_currentStep > 0)
+        {
+            _currentStep--;
+            _errorMessage = string.Empty;
+        }
+    }
+
+    private bool ValidateCurrentStep()
+    {
+        switch (_currentStep)
+        {
+            case 0:
+                if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
+                    || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
+                {
+                    _errorMessage = "All fields are required.";
+                    return false;
+                }
+                break;
+            case 1:
+                foreach (var entry in _workEntries)
+                {
+                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
+                        || entry.StartDate == default)
+                    {
+                        _errorMessage = "Company, title, and start date are required for each position.";
+                        return false;
+                    }
+                }
+                break;
+            case 2:
+                foreach (var r in _references)
+                {
+                    if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
+                        || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
+                    {
+                        _errorMessage = "All fields are required for each reference.";
+                        return false;
+                    }
+                }
+                break;
+            case 3:
+                if (string.IsNullOrWhiteSpace(_coverLetter))
+                {
+                    _errorMessage = "Please write a cover letter.";
+                    return false;
+                }
+                break;
+        }
+        return true;
+    }
+
+    private void AddWorkEntry()
+    {
+        _workEntries.Add(new WorkEntryModel());
+    }
+
+    private void RemoveWorkEntry(int index)
+    {
+        if (_workEntries.Count > 1)
+            _workEntries.RemoveAt(index);
+    }
+
+    private void AddReference()
+    {
+        if (_references.Count < 3)
+            _references.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (_references.Count > 2)
+            _references.RemoveAt(index);
+    }
+
+    private async Task SubmitApplication()
+    {
+        _isSubmitting = true;
+
+        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
+        var workEntries = _workEntries.Select(e =>
+            new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? string.Empty)
+        ).ToList();
+        var work = new WorkHistory(workEntries);
+        var references = _references.Select(r =>
+            new Reference(r.Name, r.Relationship, r.Email, r.Phone)
+        ).ToList();
+
+        var application = new JobApplication(personal, work, references, _coverLetter);
+        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
+
+        _isSubmitting = false;
+        _submitted = true;
+    }
+
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = string.Empty;
+        public string Title { get; set; } = string.Empty;
+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string? Description { get; set; }
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = string.Empty;
+        public string Relationship { get; set; } = string.Empty;
+        public string Email { get; set; } = string.Empty;
+        public string Phone { get; set; } = string.Empty;
+    }
+}
